INSERT INTO feature VALUES('nested-operation-laws','rules','Operations nested in a law or a call','rule-coincidence','partial','notable',NULL,'A theory''s call nesting an operation where the cell layer reads a value normalizes over terms under the block''s oriented rules, each operation over an indexed sort carrying the indices its sorting fixes: `orBot(cut, fail)` reaches `cut`, and a call asking one index at two sorts is refused ill sorted. A law nesting an operation over an indexed sort is read with those indices, and the kernel decides the block over the indices it re-derives, so a category''s unit laws join at `comp(id(a), id(a))`. A carried index applies an operation with indices of its own, each carried, and a law''s sides sort modulo the laws at earlier sorts, so a CwF''s identity law on terms reads and decides (#5042). An index at a sort the block''s laws rewrite is left off, so a 2-cell under a law of composition carries no hom, and a whisker distributing over vertical composition reads over objects and decides. A family''s rule nesting an operation, `add(add(m, n), k) ==> add(m, add(n, k))`, is a law of the family: its operation runs by its other rules, and the kernel admits it only when the whole system converges, every critical pair at a call below a rule''s root joined. A law whose carried index applies an operation a law at an earlier sort rewrites is refused `UndescribedMember.RewrittenIndex` (#5117). A law instantiating a variable beside an indexed sort, and a law whose carried index applies an operation whose own indices no port fixes (#4128), are still refused `UndescribedMember.NestedOperation`.','kernel-core kernel-term surface-lowering surface-lowering-base theory-computads theory-levitation','corpus/model/desc/graded-cut.gandr corpus/model/higher-cells/cat-shape.gandr corpus/surface/higher-cells/cat-shape.gandr corpus/ledger/diagnostics/UndescribedMember.NestedOperation.gandr corpus/ledger/diagnostics/UndescribedMember.RewrittenIndex.gandr crates/surface-lowering-base/tests/coincide.rs crates/kernel-term/src/theory_rules/tests.rs crates/kernel-term/src/operation_rules/tests.rs crates/surface-lowering/tests/operation.rs','corpus/ledger/features/nested-operation-laws.gandr','#4128 #5117');
